const source = $input.first().json || {};
const execution = source.execution && typeof source.execution === 'object' ? source.execution : {};
const workflow = source.workflow && typeof source.workflow === 'object' ? source.workflow : {};
const node = source.node && typeof source.node === 'object' ? source.node : {};
const error = execution.error && typeof execution.error === 'object' ? execution.error : source.error && typeof source.error === 'object' ? source.error : {};
const redact = (value, max = 4000) => {
  let text = String(value ?? '');
  text = text.replace(/(authorization\s*[:=]\s*bearer\s+)[^\s,;]+/gi, '$1[REDACTED]');
  text = text.replace(/\bBearer\s+[^\s,;]+/gi, 'Bearer [REDACTED]');
  text = text.replace(/\b(?:sk|pk|rk)-[A-Za-z0-9_-]{8,}\b/g, '[REDACTED_KEY]');
  text = text.replace(/([?&](?:api_?key|token|secret|password|signature)=)[^&\s]+/gi, '$1[REDACTED]');
  text = text.replace(/((?:api_?key|token|secret|password|cookie|session)\s*[:=]\s*)[^,;\s]+/gi, '$1[REDACTED]');
  text = text.replace(/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}(?:\.[A-Za-z0-9_-]{10,})?\b/g, '[REDACTED_JWT]');
  return text.slice(0, max);
};
const workflowName = redact(workflow.name || source.workflowName || 'unknown-workflow', 240);
const workflowId = redact(workflow.id || source.workflowId || '', 120);
const executionId = redact(execution.id || source.executionId || '', 120);
const nodeName = redact(node.name || error.node?.name || source.nodeName || 'unknown-node', 240);
const message = redact(error.message || source.message || 'Unknown workflow error', 1500);
const stack = redact(error.stack || '', 4000);
const seed = `${workflowId}|${executionId}|${nodeName}|${message}`;
let hash = 2166136261;
for (let i = 0; i < seed.length; i++) { hash ^= seed.charCodeAt(i); hash = Math.imul(hash, 16777619); }
const severity = /credential|authentication|authorization|forbidden|security|data loss/i.test(message) ? 'high' : 'normal';
return [{ json: {
  error_key: `err_${(hash >>> 0).toString(16).padStart(8, '0')}`,
  occurred_at: new Date().toISOString(),
  severity,
  workflow: { id: workflowId, name: workflowName },
  execution: { id: executionId, url: redact(execution.url || '', 500), retry_of: redact(execution.retryOf || '', 120) },
  node: { name: nodeName, type: redact(node.type || '', 200) },
  error: { name: redact(error.name || 'Error', 120), message, stack },
  data_policy: 'No failed input or output payloads included',
  config: {
    dry_run: true,
    alert_webhook_url: 'https://CONFIGURE-ME.invalid/alerts/workflow-error',
    dead_letter_webhook_url: 'https://CONFIGURE-ME.invalid/dead-letter/workflow-error'
  }
} }];
